package com.fillumina.formio.gen;

/**
 * A formio.js line that a generated page can target.
 *
 * <p>Form.io stopped publishing formio.js 5.x to its own CDN, so the two
 * supported lines are served from different hosts: the 4.x line from
 * cdn.form.io, the 5.x line from the npm package through jsdelivr.
 *
 * <p>The form JSON generated by this library is identical for every runtime
 * here. A runtime only decides which script and stylesheet the page loads, and
 * with which Bootstrap flavour.
 */
public enum FormioRuntime {

    /**
     * formio.js 4.21.2, the last 4.x release, served by cdn.form.io. Renders
     * with Bootstrap 4 and needs the Font Awesome 4 icon font.
     */
    FORMIO_JS_4(
            "4.21.2",
            "https://cdn.form.io/formiojs/4.21.2/formio.full.min.js",
            "https://cdn.form.io/formiojs/4.21.2/formio.full.min.css",
            "https://cdn.jsdelivr.net/npm/bootstrap@4.1.3/dist/css/bootstrap.min.css",
            "https://cdn.jsdelivr.net/npm/font-awesome@4.7.0/css/font-awesome.min.css",
            null),

    /**
     * formio.js 5.6.1, served through jsdelivr from the @formio/js npm
     * package. Renders with Bootstrap 5 and brings its own icon font.
     */
    FORMIO_JS_5(
            "5.6.1",
            "https://cdn.jsdelivr.net/npm/@formio/js@5.6.1/dist/formio.full.min.js",
            "https://cdn.jsdelivr.net/npm/@formio/js@5.6.1/dist/formio.full.min.css",
            "https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css",
            null,
            "bootstrap5");

    private final String version;
    private final String jsUrl;
    private final String cssUrl;
    private final String bootstrapCssUrl;
    private final String fontAwesomeCssUrl;
    private final String formioTheme;

    FormioRuntime(
            String version,
            String jsUrl,
            String cssUrl,
            String bootstrapCssUrl,
            String fontAwesomeCssUrl,
            String formioTheme) {
        this.version = version;
        this.jsUrl = jsUrl;
        this.cssUrl = cssUrl;
        this.bootstrapCssUrl = bootstrapCssUrl;
        this.fontAwesomeCssUrl = fontAwesomeCssUrl;
        this.formioTheme = formioTheme;
    }

    /**
     * @return the formio.js version this runtime serves, for example
     *         {@code 5.6.1}
     */
    public String version() {
        return version;
    }

    /**
     * @return the URL of the formio.js bundle, pinned to {@link #version()}
     */
    public String jsUrl() {
        return jsUrl;
    }

    /**
     * @return the URL of the formio.js stylesheet, pinned to
     *         {@link #version()}
     */
    public String cssUrl() {
        return cssUrl;
    }

    /**
     * @return the URL of the Bootstrap stylesheet this runtime renders with
     */
    public String bootstrapCssUrl() {
        return bootstrapCssUrl;
    }

    /**
     * @return the URL of the Font Awesome stylesheet, or null when the runtime
     *         ships its own icon font
     */
    public String fontAwesomeCssUrl() {
        return fontAwesomeCssUrl;
    }

    /**
     * @return the formio.js theme to request when creating the form, or null
     *         when the runtime has no theme option
     */
    public String formioTheme() {
        return formioTheme;
    }
}
